namespace {
std::string context;
void check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(context+": "+why);}
std::vector<Pixel> words(const JsonArray& a){std::vector<Pixel> result;for(auto v:a)result.push_back(Pixel(v.GetNumber()));return result;}
void equalPixels(const std::vector<Pixel>& actual,const JsonArray& expected,const std::string& why){const auto wanted=words(expected);if(actual==wanted)return;for(std::size_t i=0;i<std::min(actual.size(),wanted.size());++i)if(actual[i]!=wanted[i])check(false,why+" pixel "+std::to_string(i)+" got "+std::to_string(actual[i])+" wanted "+std::to_string(wanted[i]));check(false,why+" length");}
void encoded(const Document& d){if(d.colorMode()!=color_mode::Mode::Indexed)return;bool duplicates=false;std::unordered_set<int> ids;for(const auto& e:d.palette().entries)duplicates|=!ids.insert(e.id).second;
 for(int k=0;k<3;++k){try{auto out=k==0?project::encodeEditableProject(d):k==1?project::encodeRecoveryProject(d):project::encodeHistoryProject(d);check(!duplicates,"encoder accepted duplicates");auto manifest=project::readProjectManifest(out.bytes);project::Archive zip(out.bytes);check(manifest.colorMode=="indexed","encoded mode");for(const auto& c:manifest.cels)if(c.surface){const auto* runtime=d.timeline().resolveSurface(c.id).surface;const auto& s=*c.surface;check(runtime&&s.format==project::RasterFormat::Indexed&&project::decodeRaster(zip.read(s.dataFile,project::Limits{}.expandedBytes),s.dataEncoding,s.format,s.width,s.height,project::Limits{}.expandedBytes)==runtime->pixels,"encoded raw IDs");}bool gated=false;try{project::prepareEditableImport(manifest);}catch(const project::Error& e){gated=e.kind==project::ErrorKind::Unsupported;}check(gated,"indexed production admission");}catch(const project::Error& e){check(duplicates&&e.kind==project::ErrorKind::Corrupt,std::string("encoder error: ")+e.what());}}
}
}
