  if(changed){check(bool(d->history_.latest().contentHistory.dense)==row.GetNamedBoolean(L"dense"),"dense threshold");if(row.GetNamedValue(L"replayOrder").ValueType()==JsonValueType::Array){std::vector<int> order;for(auto id:words(row.GetNamedArray(L"replayOrder")))order.push_back(int(id));d->palette_.setOrder(std::move(order));}const auto current=d->palette_;if(linked)encoded(*d);d->undo();verify(*d,row,L"undo",linked);check(indexed_adjustment::samePaletteData(current,d->palette_),"undo palette");if(linked)encoded(*d);d->redo();verify(*d,row,L"redo",linked);if(linked)encoded(*d);}
