int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);check(bool(in),"missing oracle");const std::string bytes{std::istreambuf_iterator<char>(in),{}};const auto rows=JsonObject::Parse(winrt::to_hstring(bytes)).GetNamedArray(L"cases");check(rows.Size()==1470,"oracle coverage");unsigned links=0,dense=0;for(unsigned i=0;i<rows.Size();++i){const auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(row.GetNamedBoolean(L"dense"))++dense;if(i%19==0||row.GetNamedBoolean(L"dense")){RasterHistoryFixture::run(row,true);++links;}}std::cout<<rows.Size()<<" actual legacy spray cases, "<<dense<<" dense histories and "<<links<<" linked/codec variants passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
